const ORDER = { a: 0, x: 0, i: 0, c: 1, s: 2, w: 3 };
const queue = [...todo].sort((a, b) => ORDER[a.kind] - ORDER[b.kind]); // 메뉴 아이콘(몇 장 안 됨) → 스토리북 → 단어
