      if (j.cut) execFileSync(path.join(MFLUX, '.venv/bin/python'), ['-I', '-c', CUT_PY, path.join(outDir, j.file), j.cut]);
      man[j.kind][j.key] = j.file; man.h[j.kind + j.key] = hash(j.prompt).slice(0, 10); mine.add([j.kind, j.key]);
      writeMan(); // 한 장마다 저장: 중간에 Mac을 꺼도 그린 그림은 남는다
      if (++done % 10 === 0) console.log(`  ${done} / ${todo.length}`);
